/**
 * Cost Estimation
 *
 * Estimates, before a batch AI run is dispatched, the input and output
 * tokens of each request it will make: one per workout, since each workout
 * is generated by its own request. A request's input is the system prompt
 * it is sent with plus the workout's description and comments, at the
 * characters-per-token rate `@kaiord/ai` estimates with; its output is a
 * fixed allowance. The batch dialog prices each request on its own, so a
 * long-context tier applies only to a request that crosses it.
 */

import { estimateTokens } from "@kaiord/ai/providers";

import type { WorkoutRecord } from "../types/calendar-record";

const OUTPUT_TOKEN_ESTIMATE = 500;

export type TokenSplit = { input: number; output: number };

export function estimateWorkoutRequests(
  workouts: WorkoutRecord[],
  systemChars: number
): TokenSplit[] {
  return workouts.flatMap((w) => {
    if (!w.raw) return [];
    const commentChars = w.raw.comments.reduce(
      (sum, c) => sum + c.text.length,
      0
    );
    const chars = systemChars + w.raw.description.length + commentChars;
    return [{ input: estimateTokens(chars), output: OUTPUT_TOKEN_ESTIMATE }];
  });
}
